var wR = { sectId: yR, announcement: "近日山下商路多有邪修出没，外出历练者须结伴而行；归宗后记得向执事堂补录见闻。", onboarding: { summary: "从红尘中学剑，以平生所见养成剑意，在照影游尘与守拙藏锋之间走出自己的剑路。", traits: ["入世问剑", "快重由心", "此剑平生"], script: { id: "lingxiao-onboarding", title: "人间问剑", theme: "steel", backdrop: { src: "/assets/sect/onboarding/lingxiao.webp", alt: "红尘剑宗山门朝向山下城郭，负剑弟子沿石阶往来于山门与人间" }, acts: [{ id: "downhill-gate", title: "山下之门", scene: "红尘剑宗 · 山门", body: "山门立在半山，门外石阶没有隐入云海，而是一路通向炊烟初起的城郭。有人衣衫整肃，正负剑下山；也有人带着满身风尘，从长路归来。", speaker: "守门弟子：“上山学剑，下山用剑。红尘剑宗的路，从来要走两遍。”", backgroundPosition: "58% 46%", tone: "mist" }, { id: "ask-the-sword", title: "先问其剑", scene: "红尘剑宗 · 问剑堂", body: "传功长老没有命你劈开试剑石，只从旧架上取下一柄寻常铁剑，横放在你面前。剑锋不见灵光，剑鞘上却留着许多经年磨痕。", speaker: "传功长老：“剑能斩什么，不难。难的是你要知道，什么不该斩。”", backgroundPosition: "30% 52%", tone: "steel" }, { id: "sword-record", title: "红尘剑录", scene: "红尘剑宗 · 剑录阁", body: "旧卷中既有剑招，也夹着地名、人名、残缺书信与未能兑现的约定。许多段落只有寥寥数笔，却被后来者反复翻阅。", speaker: "守阁长老：“剑法可以传，平生不可照抄。前人的答案，只能替你问出自己的问题。”", backgroundPosition: "72% 38%", tone: "stillness" }, { id: "two-sword-paths", title: "两道剑途", scene: "红尘剑宗 · 照影崖", body: "崖前剑影一快一重。快剑连绵，转瞬已在石壁留下数道剑痕；重剑静立，直至来势逼近，才以后发一击震开尘土。", speaker: "传功长老：“照影游尘，见招而变；守拙藏锋，承势而决。剑路不同，最后问的却是同一件事。”", backgroundPosition: "42% 44%", tone: "mist" }, { id: "one-life-one-sword", title: "此剑平生", scene: "红尘剑宗 · 弟子名册前", body: "你的名字被写入弟子名册，《红尘剑录》中属于你的那一页仍然空白。长老合上旧卷，将那柄铁剑连同剑鞘一并交到你手中。", speaker: "传功长老：“今日不必写。等你真正明白为何出剑，再回来落这一笔。”", backgroundPosition: "54% 35%", tone: "steel" }] } }, map: { image: "/assets/sect/lingxiao-map.webp", alt: "红尘剑宗殿阁、试剑台、工坊、矿场与药田沿山路连接山下城郭的水墨鸟瞰图", hotspots: [{ id: "hall", label: "问剑堂", route: "/game/sect/hall", permission: "sect.hall.view", left: "46%", top: "25%", note: "身份 · 同门 · 周俸" }, { id: "archive", label: "剑录阁", route: "/game/sect/archive", facility: "archive", permission: "sect.archive.use", left: "15%", top: "31%", note: "心法研习" }, { id: "cliff", label: "照影崖", route: "/game/sect/enlightenment-cliff", permission: "sect.enlightenment.use", left: "88%", top: "19%", note: "流派 · 参悟" }, { id: "arena", label: "试剑台", route: "/game/sect/arena", permission: "sect.arena.use", left: "57%", top: "64%", note: "神通 · 战术 · 小比" }, { id: "affairs", label: "执事堂", route: "/game/sect/affairs", permission: "sect.tasks.use", left: "42%", top: "48%", note: "日常 · 周常 · 晋升" }, { id: "treasury", label: "宗门宝库", route: "/game/sect/treasury", permission: "sect.shop.use", left: "57%", top: "36%", note: "贡献兑换" }, { id: "industries", label: "百业院", route: "/game/sect/industries", permission: "sect.construction.view", left: "55%", top: "53%", note: "设施建设 · 灵石捐献" }, { id: "cultivation", label: "养剑室", route: "/game/sect/cultivation-room", facility: "cultivation_room", permission: "sect.facility.cultivation.use", left: "17%", top: "72%", note: "闭关修炼 · 设施灵效" }, { id: "alchemy", label: "丹房", route: "/game/sect/alchemy", facility: "workshop", permission: "sect.facility.alchemy.use", left: "64%", top: "43%", note: "炼丹 · 设施灵效" }, { id: "refinery", label: "铸剑坊", route: "/game/sect/refinery", facility: "workshop", permission: "sect.facility.refinery.use", left: "69%", top: "51%", note: "炼器 · 设施灵效" }, { id: "vein", label: "灵脉矿场", route: "/game/sect/spirit-vein", facility: "spirit_vein", permission: "sect.spirit_vein.view", left: "84%", top: "46%", note: "矿场巡视 · 灵石收益 · 采矿" }, { id: "garden", label: "药田", route: "/game/sect/herb-garden", facility: "herb_garden", permission: "sect.herb_garden.view", left: "83%", top: "75%", note: "草木长势 · 产出待开放" }, { id: "gate", label: "山门", route: "/game/sect/gate", permission: "sect.gate.view", left: "48%", top: "77%", note: "山门动态 · 清扫差事", visitor: { description: "山门外的石阶直通城郭，守门弟子会为外客登记来意与拜帖。" } }, { id: "cave", label: "私人洞府", route: "/game/sect/cave", permission: "sect.cave.view", left: "26%", top: "66%", note: "弟子居所" }, { id: "formation", label: "护山大阵", facility: "formation", permission: "sect.formation.view", left: "49%", top: "8%", note: "宗门战后续开放", locked: !0, visitor: { description: "剑痕沿群峰与山路首尾相接，外客只能在阵外看见偶尔掠过云层的锋光。" } }] }, facilityLabels: { archive: "剑录阁", cultivation_room: "养剑室", workshop: "丹器坊", spirit_vein: "灵脉", herb_garden: "药田", formation: "护山大阵" }, lockedFacilities: ["formation"], scenes: { map: { title: "红尘剑宗舆图", description: "殿阁沿山势铺开，主路穿过山门直通城郭。择一处前往，继续今日的宗门事务。", loadingText: "山路与诸院渐次显现……" }, hall: { title: "问剑堂", description: "堂中不设试剑石，只悬历代门人的旧剑与归宗名册；身份玉牒、俸禄名册皆由录事在此核验。" }, affairs: { title: "执事堂", description: "木榜上新令墨迹未干，今日差事、周录与晋升试炼各有封签；诸令皆可逐一揭下，办妥后回堂交卷领赏。", loadingText: "执事正整理今日委托……" }, archive: { title: "剑录阁", description: "檀木长架上既有六卷心法，也收着历代弟子的行剑手记；在此逐卷研习，不必再穿行别阁。", loadingText: "剑录阁卷帙正在归架……" }, paths: { title: "照影崖", description: "崖壁遍布历代门人留下的试剑痕迹，快重二道皆由此分流；择定道途后，沿经脉继续参悟。", loadingText: "崖前剑影正在散开……" }, arena: { title: "试剑台", description: "演武场中央阵纹已启，宗门神通将在当前流派与参悟方案下显化威能。", loadingText: "试剑台阵纹徐徐亮起……" }, treasury: { title: "宗门宝库", description: "铜锁开启，木架深处的常备物资与本周珍材依次显露；持弟子令牌即可按贡献支取。", loadingText: "宝库执事正在清点本周库存……" }, industries: { title: "百业院", description: "各处设施的等级与建设进度依次列于案台，弟子可择一处捐献灵石。", loadingText: "百业院正在汇总设施进度……" }, cultivation: { title: "养剑室", description: "聚灵阵纹绕蒲团缓缓流转，静香已燃；定下闭关年数，宗门灵气会在结算时自然汇入。", loadingText: "聚灵阵正在汇拢灵气……" }, alchemy: { title: "丹房", description: "赤铜丹炉吞吐灵焰，药柜沿墙依性归置；投下灵材、定住丹意，便可在此守候成丹。", loadingText: "丹房灵焰正在温炉……" }, refinery: { title: "铸剑坊", description: "地火自山腹引入锻台，冷铁与灵材依次落位；选定器型后即可在此开炉成器。", loadingText: "铸剑坊地火正在升温……" }, spiritVein: { title: "灵脉矿场", description: "矿壁间青光沿岩隙缓缓游走，执事循脉定井；每周俸禄中的灵石加成皆从此处汇出。", loadingText: "矿道深处灵辉渐明……" }, herbGarden: { title: "宗门药田", description: "层层药畦顺山势铺开，灵泉沿石渠润过根须；药田产出玩法后续开放。", loadingText: "药田晨雾正在散去……" }, gate: { title: "山门", description: "石阶从门外一路通往山下城郭，守门弟子在晨钟后换过值守；今日宗门内外动静都写在门侧木牌上。", loadingText: "山门晨钟沿石阶传来……" }, cave: { title: "私人洞府", description: "石门隔去峰间喧声，竹影从纸窗落入蒲团；这是内门弟子留在宗门中的一处清修居所。", loadingText: "洞府石门映入云间……" } }, rooms: { affairs: { description: "旧剑与功簿分列堂中，三席经办之人各守一案。寻到对应之人，便可当面接下或交回事务。", actors: { daily: { id: "lingxiao-lin-yanqiu", name: "陆青崖", greeting: "今日事务已经理清，你先说想办哪一桩。" }, weekly: { id: "lingxiao-gu-wenfeng", name: "裴守拙", greeting: "本周功簿在此，小比与悬赏也都记着。" }, promotion: { id: "lingxiao-xie-tingyun", name: "听剑老人", greeting: "晋升问的不是锋芒多少，而是这一剑为何而出。" } } }, hall: { actors: { registry: { id: "lingxiao-shen-chijian", name: "顾怀真", greeting: "玉牒和同门名录都已理好，你想查哪一项？" }, stipend: { id: "lingxiao-wen-fenglu", name: "柳七", greeting: "本周该发的都已算清，要核对还是领取，你直说便是。" } } }, treasury: { actors: { keeper: { id: "lingxiao-cangfeng-weng", name: "叶归鸿", greeting: "架上的东西各有标价，你看中哪件便报来。" } } }, industries: { actors: { construction: { id: "lingxiao-zhu-baigong", name: "杜长庚", greeting: "各处设施修到哪里、还差多少，我都能说给你听。" }, donation: { id: "lingxiao-shi-sanjin", name: "苗小满", greeting: "今日可择一处设施捐献灵石，我替你登记。" } } }, archive: { actors: { keeper: { id: "lingxiao-xie-guanjian", name: "温不言", greeting: "六卷心法都在架上，先说你想读哪一卷。" } } }, paths: { actors: { guide: { id: "lingxiao-wenjian-sou", name: "祝平生", greeting: "路要自己走，眼下看不明白的地方可以先问。" } } }, arena: { actors: { instructor: { id: "lingxiao-fu-shifeng", name: "霍千钧", greeting: "招式合不合手，上场一试便知；先把你的神通排给我看。" }, marshal: { id: "lingxiao-chen-shoutai", name: "苏放鹤", greeting: "场中已经收拾妥当，有小比在身便可入场。" } } }, cultivation: { actors: { keeper: { id: "lingxiao-su-jing", name: "晏无声", greeting: "阵息正稳，想问此地灵效，还是现在入静？" } } }, alchemy: { actors: { keeper: { id: "lingxiao-yan-danshi", name: "程晚照", greeting: "火候正好，想先问丹房灵效，还是直接开炉？" } } }, refinery: { actors: { keeper: { id: "lingxiao-ou-yeqing", name: "谭折柳", greeting: "地火还稳，想先问器坊灵效，还是就此动手？" } } }, spiritVein: { actors: { keeper: { id: "lingxiao-luo-tingmai", name: "邵沉川", greeting: "矿道巡视封签已经备好，有差事便在这里核对。" }, facility: { id: "lingxiao-lingmai-kuangchang", name: "灵脉矿场", greeting: "矿壁间青光沿岩隙缓缓游走，脉息沉稳如常。" } } }, herbGarden: { actors: { keeper: { id: "lingxiao-he-caowei", name: "秦晚晴", greeting: "晨露刚退，田里长势不错，草木值录已经写好了。" }, facility: { id: "lingxiao-zongmen-yaotian", name: "宗门药田", greeting: "层层药畦顺山势铺开，灵泉正沿石渠润过根须。" } } }, gate: { actors: { keeper: { id: "lingxiao-zhou-shanmen", name: "骆长亭", greeting: "山下已经有人来往，今日来客与山门动静都记在这里。" }, facility: { id: "lingxiao-shanmen", name: "山门", greeting: "门外石阶一路通向山下，晨风卷来几片新落的叶子。" } } } }, terms: { pathChanges: "剑路变化", meridianPractice: "剑道参悟", meridianLoadout: "参悟方案", abilityChanges: "神通变化", returnToAffairs: "返回执事堂" } };
var RR = { id: "wuxiang", name: "无相禅宗", description: "此宗不避魔心，不弃色身。门人以皮囊为道场，以气血燃业火；佛法用来照见诸苦，魔功用来横渡诸苦。", raceIds: ["human"], configVersion: 2, methods: [{ id: "wuxiang-canon", slot: 1, name: "《无相真解》", isPrimary: !0, description: "观色身诸相皆无定相，于一念之间容佛、容魔，亦容无相。" }, { id: "blood-lotus", slot: 2, name: "《血海生莲》", description: "血海不净，莲亦由此而生；知其污浊，方能借之渡身。" }, { id: "white-bone", slot: 3, name: "《白骨照身》", description: "去皮肉浮相，见白骨本真；以朽坏之身承受来力。" }, { id: "wrathful-ming", slot: 4, name: "《明王降魔》", description: "明王怒目，不为嗔心，只借烈相斩断迟疑。" }, { id: "six-senses", slot: 5, name: "《六根守识》", description: "声色香味触法皆至于前，心识自守，不随外境转移。" }, { id: "reed-crossing-method", slot: 6, name: "《一苇渡苦》", description: "苦海无边，轻身不待舟楫；一苇所向，只问彼岸。" }], abilities: [{ id: "flower-heart", kind: "default", baseName: "拈花叩心", description: "指间拈花，叩问的却是敌我同一颗心。佛相立其因，魔相照其果，无相令因果同现。", role: "generator", unlock: { type: "method", methodId: "wuxiang-canon", level: 1 } }, { id: "blood-tide", kind: "active", baseName: "血海听潮", description: "不拒血海来潮，先听清每一道苦声从何处生，再于回澜时借势渡身。", role: "defensive", unlock: { type: "method", methodId: "blood-lotus", level: 1 } }, { id: "three-knocks", kind: "active", baseName: "三叩业门", description: "一叩问因，二叩问果，三叩之后，门内门外皆由一念开合。", role: "combo", unlock: { type: "method", methodId: "white-bone", level: 3 } }, { id: "observe-calamity", kind: "active", baseName: "闭目观劫", description: "闭目并非不见，而是不被劫相夺去心神；开眼之时，劫已照明。", role: "defensive", unlock: { type: "method", methodId: "wrathful-ming", level: 3 } }, { id: "five-skandhas", kind: "active", baseName: "照见五蕴", description: "色受想行识逐一照破。佛相辨其虚实，魔相借火自渡，无相令诸蕴俱空。", role: "utility", unlock: { type: "method", methodId: "six-senses", level: 3 } }, { id: "reed-crossing", kind: "active", baseName: "一苇横江", description: "江阔浪急，脚下只留一苇；佛相守住此岸，魔相强渡彼岸，无相则知两岸非岸。", role: "defensive", unlock: { type: "method", methodId: "reed-crossing-method", level: 3 } }, { id: "turn-form", kind: "active", baseName: "一念未生", description: "心念未足时，一念尚伏于心；心念既成，佛、魔与无相只在翻掌之间。", role: "finisher", unlock: { type: "method", methodId: "wuxiang-canon", level: 5 } }, { id: "wuxiang-runtime", kind: "passive", baseName: "不坏色身", description: "色身即是道场：最大气血提高，身陷危境时更能承受迎面而来的伤害。", role: "defensive", unlock: { type: "always" }, visibility: "internal" }, { id: "mirror-core", kind: "passive", baseName: "明镜照业", description: "来力皆留其痕，因满果熟时照还来处。", role: "defensive", unlock: { type: "active_path", pathId: "mirror-karma" }, visibility: "internal" }, { id: "demon-core", kind: "passive", baseName: "魔心渡厄", description: "以气血作舟、心念作楫，于一息将尽之际横渡生死。", role: "combo", unlock: { type: "active_path", pathId: "demon-crossing" }, visibility: "internal" }], onboarding: { initialContribution: 30, initialMethods: { "wuxiang-canon": 5, "blood-lotus": 3, "white-bone": 3, "wrathful-ming": 3, "six-senses": 3, "reed-crossing-method": 3 }, initialAbilityLoadout: ["turn-form", "blood-tide", "three-knocks", "observe-calamity"] }, paths: [{ id: "mirror-karma", name: "明镜照业", description: "以承受制造因，以魔相兑现果。来力不急于拒绝，只把每一道因果留在镜中；佛相立因，魔相现报，无相令因果同时照见。", minRealm: "筑基", minRealmStage: "中期", layers: [{ id: "1", order: 1, label: "第一层", minRealm: "筑基", minRealmStage: "中期", cost: { cultivationExp: 5000, comprehensionInsight: 100, spiritStones: 25000 } }, { id: "2", order: 2, label: "第二层", minRealm: "金丹", minRealmStage: "圆满", cost: { cultivationExp: 20000, comprehensionInsight: 100, spiritStones: 1e5 } }, { id: "3", order: 3, label: "第三层", minRealm: "化神", minRealmStage: "中期", cost: { cultivationExp: 80000, comprehensionInsight: 100, spiritStones: 400000 } }, { id: "4", order: 4, label: "第四层", minRealm: "炼虚", minRealmStage: "圆满", cost: { cultivationExp: 320000, comprehensionInsight: 100, spiritStones: 1600000 } }, { id: "5", order: 5, label: "第五层", minRealm: "大乘", minRealmStage: "中期", cost: { cultivationExp: 1280000, comprehensionInsight: 100, spiritStones: 6400000 } }, { id: "ultimate", order: 6, label: "终式", minRealm: "渡劫", minRealmStage: "圆满", cost: { cultivationExp: 5120000, comprehensionInsight: 100, spiritStones: 25600000 } }], defaultTacticId: "guard", tactics: [{ id: "guard", name: "守镜", description: "优先保持3层业痕与防守状态；3层业痕且达到3点心念，或达到5点心念后入魔，优先使用防御神通维持血线。" }, { id: "present", name: "现报", description: "至少1层业痕且达到3点心念便入魔，优先使用可即时消费业痕的攻击神通。" }, { id: "formless", name: "无相", description: "原则上积满6点心念再显无相；低于35%气血且已有3点心念时允许提前入魔自救。" }], presentation: { highlights: [{ name: "受击留业", description: "佛相承受敌方直接伤害，积累业痕并即时返还部分来力。" }, { name: "逐层现报", description: "佛相奠定招式根基；显化魔相时照见现报，显化无相时再现最终变化。" }, { name: "一念两照", description: "显化无相时，同一门神通会兼具佛相本式、魔相变化与无相变化。" }], abilityChanges: { "flower-heart": "佛相伤敌并留下叩心戒；魔相借业痕问罪追击、封住敌招；无相再发一击，并为自身留下业痕。", "blood-tide": "佛相提供护盾与听潮减伤；魔相消费业痕恢复并登记受击反击；无相额外加厚护盾。", "three-knocks": "佛相三击并留下新的业门；魔相借业痕引爆目标原有的业门；无相在旧门尽空后再发一击。", "observe-calamity": "佛相架势抵御一次直接伤害；魔相消费业痕令减伤同时反击；无相将架势扩展为两次。", "five-skandhas": "佛相伤敌并驱散敌方增益；魔相借业痕净化自身；无相额外伤敌并获得护盾。", "reed-crossing": "佛相保护下一次直接受击；魔相消费业痕令防护触发时反击；无相额外获得护盾。", "turn-form": "3～5点心念可使之后两门神通显化魔相；6点心念可使下一门神通显化无相。" } }, nodes: [{ id: "mirror-vow-body", layerId: "1", name: "戒由身起", description: "所有佛相神通气血成本提高1%；成功施展后获得2%最大气血护盾。" }, { id: "mirror-guest-in-mirror", layerId: "1", name: "镜中留客", description: "每轮首次受到敌方直接伤害时，额外留下1层业痕。" }, { id: "mirror-fruit-in-time", layerId: "1", name: "果不逾时", description: "每层业痕提供的佛相反伤比例由3%提高至4%。" }, { id: "mirror-loud-flower", layerId: "2", name: "花落有声", description: "叩心戒的伤害衰减由10%提高至18%。" }, { id: "mirror-welcome-tide", layerId: "2", name: "潮来不拒", description: "血海听潮的直接伤害减免由15%提高至25%。" }, { id: "mirror-fourth-knock", layerId: "2", name: "门叩第四声", description: "三叩业门额外留下第四层业门；倒叩时允许追加第四段明确伤害。" }, { id: "mirror-see-guest", layerId: "3", name: "闭目见客", description: "闭目观劫首次直接伤害减免由35%提高至50%。" }, { id: "mirror-skandhas-mark", layerId: "3", name: "蕴去痕留", description: "照见五蕴成功驱散增益时获得2层业痕。" }, { id: "mirror-carry-karma", layerId: "3", name: "一苇载业", description: "一苇横江的直接伤害减免由40%提高至50%。" }, { id: "mirror-form-beyond", layerId: "4", name: "相外有相", description: "魔相止观的直接伤害减免由20%提高至30%。" }, { id: "mirror-back-demon", layerId: "4", name: "镜背生魔", description: "每次进入魔相时，第一门神通无需消耗业痕，也能触发一次现报；无相不受影响。" }, { id: "mirror-formless-two", layerId: "4", name: "一念两照", description: "成功施展无相神通后额外获得2层业痕；《一念无间》气血成本增加2%。" }, { id: "mirror-full-light", layerId: "5", name: "业满成光", description: "业痕满层时，佛相即时反伤额外提高5%。" }, { id: "mirror-fast-fruit", layerId: "5", name: "现报无迟", description: "现报成功后，攻击神通额外造成0.20倍物攻伤害；自身防御神通额外获得4%最大气血护盾。" }, { id: "mirror-return-source", layerId: "5", name: "照还来处", description: "每次实际消耗1层业痕触发现报时，恢复2%最大气血；免费现报不触发。" }, { id: "mirror-not-platform", layerId: "ultimate", name: "明镜非台", description: "佛相且业痕满层时，受到的直接伤害降低10%。" }, { id: "mirror-all-karma", layerId: "ultimate", name: "万业同门", description: "无相现报实际消耗业痕后，会再尝试消耗1层；成功时攻击神通额外造成0.60倍物攻伤害，防御神通获得8%最大气血护盾。" }, { id: "mirror-return-thought", layerId: "ultimate", name: "来去一念", description: "成功施展无相神通后返还2点心念。" }] }, { id: "demon-crossing", name: "魔心渡厄", description: "以佛相主动沉血，以魔相强渡两息，以无相令燃血与渡厄同时显化。气血不是怒气的别名，而是每一门神通真正支付的渡河之资。", minRealm: "筑基", minRealmStage: "中期", layers: [{ id: "1", order: 1, label: "第一层", minRealm: "筑基", minRealmStage: "中期", cost: { cultivationExp: 5000, comprehensionInsight: 100, spiritStones: 25000 } }, { id: "2", order: 2, label: "第二层", minRealm: "金丹", minRealmStage: "圆满", cost: { cultivationExp: 20000, comprehensionInsight: 100, spiritStones: 1e5 } }, { id: "3", order: 3, label: "第三层", minRealm: "化神", minRealmStage: "中期", cost: { cultivationExp: 80000, comprehensionInsight: 100, spiritStones: 400000 } }, { id: "4", order: 4, label: "第四层", minRealm: "炼虚", minRealmStage: "圆满", cost: { cultivationExp: 320000, comprehensionInsight: 100, spiritStones: 1600000 } }, { id: "5", order: 5, label: "第五层", minRealm: "大乘", minRealmStage: "中期", cost: { cultivationExp: 1280000, comprehensionInsight: 100, spiritStones: 6400000 } }, { id: "ultimate", order: 6, label: "终式", minRealm: "渡劫", minRealmStage: "圆满", cost: { cultivationExp: 5120000, comprehensionInsight: 100, spiritStones: 25600000 } }], defaultTacticId: "trial-fire", tactics: [{ id: "trial-fire", name: "试火", description: "达到3点心念且低于65%气血时入魔；危急时先以攻击吸血，再用防御神通稳住血线。" }, { id: "sink-boat", name: "沉舟", description: "尽量积至5点心念并主动压至50%气血以下，入魔后优先连续使用攻击神通收束。" }, { id: "one-thought", name: "一念", description: "优先积满6点心念使用无相；低于30%气血时允许以3点心念提前入魔自救。" }], presentation: { highlights: [{ name: "主动沉血", description: "佛相支付当前气血施展神通，以真实代价换取心念；防御神通可积蓄更多心念。" }, { name: "两息渡厄", description: "进入魔相后，接下来两门宗门神通都会显现各自的魔相变化，并共享减伤、免控与吸血之效。" }, { name: "佛魔同炉", description: "显化无相时，同一门神通会兼具佛相本式、魔相变化与无相变化。" }], abilityChanges: { "flower-heart": "佛相伤敌并留下心隙；魔相再发摘心重击并多留一层心隙；无相根据目标已损气血收束。", "blood-tide": "佛相重血换取护盾与下一击强化；魔相加厚护盾并令血潮命中回血；无相立即回生并强化血潮。", "three-knocks": "佛相三击，并在自身气血较低时强化末击；魔相再发一记重击；无相在濒危时发动必定暴击的无生之击。", "observe-calamity": "佛相降低下一次直接伤害；魔相令承劫后反击；无相再获得护盾。", "five-skandhas": "佛相净化并在成功时获得心念；魔相获得护盾与下一击强化；无相再净化一个减益。", "reed-crossing": "佛相获得护盾与下一击减伤；魔相进一步强化两者；无相在濒危时恢复气血。", "turn-form": "3～5点心念可无额外气血成本进入魔相两式并获得渡厄护体与护盾；6点心念可支付少量气血使下一门神通显化无相。" } }, nodes: [{ id: "demon-blood-oil", layerId: "1", name: "血作灯油", description: "所有佛相神通气血成本提高1%；成功施展后获得2%最大气血护盾。" }, { id: "demon-three-shores", layerId: "1", name: "三岸留痕", description: "每场战斗首次因自身神通成本降至35%气血以下时，获得8%最大气血护盾。" }, { id: "demon-bone-tide", layerId: "1", name: "潮伏骨中", description: "血海听潮获得的基础护盾由10%提高至15%最大气血。" }, { id: "demon-flower-inward", layerId: "2", name: "花开向内", description: "心隙令下一次宗门直接伤害提高25%。" }, { id: "demon-no-return-tide", layerId: "2", name: "潮不回头", description: "血海听潮生成的下一门宗门直接伤害加成由20%提高至30%；无相仍以30%为准。" }, { id: "demon-third-outside", layerId: "2", name: "门外三声", description: "三叩业门强化第三击的气血线由45%提高至55%。" }, { id: "demon-slow-fire", layerId: "3", name: "劫火缓行", description: "闭目观劫的直接伤害减免由40%提高至50%。" }, { id: "demon-skandhas-fuel", layerId: "3", name: "五蕴作薪", description: "照见五蕴的佛相净化数量由1提高至2；显化无相时共净化3个减益。" }, { id: "demon-short-reed", layerId: "3", name: "苇短水长", description: "一苇横江的佛相直接伤害减免由20%提高至30%；魔相最终提高到40%。" }, { id: "demon-first-thought", layerId: "4", name: "第一念魔", description: "进入魔相或无相时获得第一念：下一门攻击神通额外造成0.35倍物攻伤害，防御神通获得5%最大气血护盾。" }, { id: "demon-second-shore", layerId: "4", name: "第二岸苦", description: "魔相期间每成功施展一门宗门神通，恢复2.5%最大气血；无相仅触发一次。" }, { id: "demon-two-gates", layerId: "4", name: "两门同渡", description: "进入魔相时获得的护盾由6%提高至10%最大气血。" }, { id: "demon-body-breaks", layerId: "5", name: "身坏心明", description: "每场战斗首次因自身神通成本降至30%气血以下时，获得1回合控制免疫。" }, { id: "demon-blood-empty", layerId: "5", name: "血尽潮生", description: "每场战斗首次因自身神通成本降至25%气血以下时，恢复5%最大气血。" }, { id: "demon-leave-boat", layerId: "5", name: "渡后留舟", description: "魔相结束时获得6%最大气血护盾；无相结束不触发。" }, { id: "demon-one-furnace", layerId: "ultimate", name: "佛魔同炉", description: "强化六门神通的无相变化，使收束伤害、恢复、护盾或净化获得提升。" }, { id: "demon-no-gap", layerId: "ultimate", name: "一息无间", description: "魔相与无相的单行动吸血上限提高至12%最大气血，但渡厄直接伤害减免由20%降低至10%。" }, { id: "demon-look-back", layerId: "ultimate", name: "回首彼岸", description: "魔相或无相结束时，若存活且低于20%气血，恢复5%最大气血；每次转相最多一次。" }] }] };
var PR = "wuxiang";
var DR = { elderTrial: { name: "空慈方丈·试炼化身", description: "佛魔二相同现，以色身与业火检验来者道心。" }, facilityNames: { archive: "贝叶藏", cultivation_room: "止观室", workshop: "火供院" } };
var qa = (e, i, n, a, t, r, s, o, d) => ({ id: e, label: i, left: n, top: a, route: t, permission: r, note: s, facility: o, visitor: d }), KR = { sectId: PR, announcement: "晨钟后将开一场无相问心会，愿照见本念者可赴旧铜镜前静坐，不拘佛魔二途。", onboarding: { summary: "把色身视作道场，在佛相、魔相与无相之间照见苦、承受苦、横渡苦。", traits: ["佛魔同修", "以身渡厄", "临危转念"], script: { id: "wuxiang-onboarding", title: "无相照身", theme: "ember", backdrop: { src: "/assets/sect/onboarding/wuxiang.webp", alt: "黑白双峰与血莲池之间，一座未合圆环形山门立在雾中" }, acts: [{ id: "nondual-gate", title: "不二门", scene: "无相禅宗 · 不二门", body: "山门没有门扇，门额只留着一道未合的圆。钟声越过黑白双峰，也越过山间那片暗红莲池；知客僧向你合掌。", speaker: "知客僧：“不必先证明清净，肯照见自己，便可入门。”", backgroundPosition: "52% 40%", tone: "stillness" }, { id: "bronze-mirror", title: "铜镜照身", scene: "无相禅宗 · 旧镜前", body: "旧铜镜里没有佛光，也没有魔影，只有一路跋涉至此的你。灯火照过衣上的尘，也照过每一道尚未说出口的迟疑。", speaker: "知客僧：“你怕的是痛苦，还是那个会在痛苦里变得陌生的自己？”", backgroundPosition: "72% 56%", tone: "stillness" }, { id: "buddha-and-demon", title: "佛与魔", scene: "无相禅宗 · 问身场", body: "白衣门人迎着来势，把因果稳稳留在身前；红衣门人踏进险境，以自身作舟，强渡将倾的一刻。这里的佛与魔不是善恶两张面具，而是面对苦难时都要付诸本心的选择。", backgroundPosition: "40% 48%", tone: "ember" }, { id: "body-as-dojo", title: "色身道场", scene: "无相禅宗 · 诸院", body: "药师从血莲池采露，火供院的锤声慢而不绝，面壁窟里有人静坐到天明。无相门人不厌弃身体，也不纵容欲念；皮囊会痛、会倦、会留下痕迹，正因如此，它才是最诚实的道场。", backgroundPosition: "30% 58%", tone: "mist" }, { id: "unfinished-circle", title: "圆未合", scene: "无相禅宗 · 名牒前", body: "知客僧在你的名牒旁落下一点墨。钟声再起，那道未完的圆仿佛正等你迈入其中。", speaker: "知客僧：“能见诸苦，不必逃；能借诸苦，不可欺心。最后这一笔，由你自己来合。”", backgroundPosition: "52% 35%", tone: "ember" }] } }, map: { image: "/assets/sect/wuxiang-map.webp", alt: "无相禅宗黑白双峰、血池、佛窟与诸院落的水墨鸟瞰图", hotspots: [qa("hall", "无相殿", "48%", "22%", "/game/sect/hall", "sect.hall.view", "身份 · 同门 · 周俸"), qa("archive", "贝叶藏", "24%", "45%", "/game/sect/archive", "sect.archive.use", "心法研习", "archive"), qa("cliff", "照业壁", "18%", "24%", "/game/sect/enlightenment-cliff", "sect.enlightenment.use", "流派 · 参悟"), qa("arena", "问身场", "45%", "57%", "/game/sect/arena", "sect.arena.use", "神通 · 战术 · 小比"), qa("affairs", "知客寮", "35%", "46%", "/game/sect/affairs", "sect.tasks.use", "日常 · 周常 · 晋升"), qa("treasury", "七宝库", "61%", "68%", "/game/sect/treasury", "sect.shop.use", "贡献兑换"), qa("industries", "营造院", "49%", "78%", "/game/sect/industries", "sect.construction.view", "设施建设 · 灵石捐献"), qa("cultivation", "止观室", "13%", "62%", "/game/sect/cultivation-room", "sect.facility.cultivation.use", "闭关修炼 · 设施灵效", "cultivation_room"), qa("alchemy", "药师寮", "72%", "51%", "/game/sect/alchemy", "sect.facility.alchemy.use", "炼丹 · 设施灵效", "workshop"), qa("refinery", "火供院", "81%", "71%", "/game/sect/refinery", "sect.facility.refinery.use", "炼器 · 设施灵效", "workshop"), qa("vein", "骨玉窟", "90%", "45%", "/game/sect/spirit-vein", "sect.spirit_vein.view", "矿场巡视 · 灵石收益 · 采矿", "spirit_vein"), qa("garden", "血莲池", "70%", "39%", "/game/sect/herb-garden", "sect.herb_garden.view", "草木长势 · 产出待开放", "herb_garden"), qa("gate", "不二门", "49%", "85%", "/game/sect/gate", "sect.gate.view", "山门动态 · 清扫差事", void 0, { description: "不二门没有门扇，知客僧在未合圆环下为外客验明拜帖。" }), qa("cave", "面壁窟", "88%", "36%", "/game/sect/cave", "sect.cave.view", "弟子居所"), { id: "formation", label: "两界曼荼罗", left: "80%", top: "13%", permission: "sect.formation.view", note: "宗门战后续开放", facility: "formation", locked: !0, visitor: { description: "黑白双峰与血莲池共同构成阵势，来客立于界外，只能看见未合圆环缓慢转动。" } }] }, facilityLabels: { archive: "贝叶藏", cultivation_room: "止观室", workshop: "火供院", spirit_vein: "骨玉窟", herb_garden: "血莲池", formation: "两界曼荼罗" }, lockedFacilities: ["formation"], scenes: { map: { title: "无相禅宗舆图", description: "黑白二峰隔血池相望，诸院不分佛魔，只依门人当下一念显出不同面目。", loadingText: "钟声正从血池上渡来……" }, hall: { title: "无相殿", description: "殿中不塑金身，只有一面照见来者全身的旧铜镜；身份玉牒与周俸名册置于镜下。" }, affairs: { title: "知客寮", description: "晨钟后三炷香内，新差事会被写上白榜；接下便是今日与自身色身结下的因。" }, archive: { title: "贝叶藏", description: "六卷心法分别藏在六只旧木匣中，贝叶上既有朱砂佛偈，也有后来人以血补下的旁注。" }, paths: { title: "照业壁", description: "石壁正面如镜，背面焦黑。两条道途的痕迹交映于此，等待弟子静心参悟。" }, arena: { title: "问身场", description: "场中木人不会退让。佛相留下因，魔相兑现果，无相只在心念圆满的一念间显现。" }, cultivation: { title: "止观室", description: "室内只容一席一灯。呼吸落在皮肉，念头落在灯芯，直到两者都不再需要命名。" }, alchemy: { title: "药师寮", description: "血莲、骨玉与寻常灵草分柜存放，药师只问药性，不问净秽。" }, refinery: { title: "火供院", description: "炉火映出忿怒相，锤声却始终缓慢；每一件法器都要在火中去掉多余的名字。" }, spiritVein: { title: "骨玉窟", description: "白色矿髓沿黑岩生长，如同山腹中的巨大骨骼。" }, herbGarden: { title: "血莲池", description: "暗红池水并无腥气，莲叶托着晨露；药田产出玩法后续开放。" }, gate: { title: "不二门", description: "门额只有一道未写完的圆。来者从哪一侧入门，都由同一道钟声迎接。" }, cave: { title: "面壁窟", description: "石窟里没有装饰，只有前人留下的坐痕与指印。" } }, rooms: { affairs: { description: "晨钟余音尚在，白榜上的差事由三位僧人分掌；领下一事，便结下一段今日之因。", actors: { daily: { id: "wuxiang-mingchen", name: "法明", greeting: "白榜上的日务都在这里，肯做哪一件便说。" }, weekly: { id: "wuxiang-zhaoye", name: "慧觉", greeting: "功簿只记所行，不替人评说，你可自行查问。" }, promotion: { id: "wuxiang-due", name: "空慈方丈", greeting: "要过此关，先要肯照见自己带来的业。" } } }, hall: { actors: { registry: { id: "wuxiang-huiming", name: "慧澄", greeting: "玉牒与僧录皆在案前，想查哪一项便问。" }, stipend: { id: "wuxiang-mingji", name: "明济", greeting: "本周供养已经分定，领取之前也可先核对。" } } }, treasury: { actors: { keeper: { id: "wuxiang-kongzang", name: "寂照禅师", greeting: "诸物各待其用，你想看哪一件？" } } }, industries: { actors: { construction: { id: "wuxiang-mingzhu", name: "行深", greeting: "一砖一木皆有来处，各处建设可逐项说与你听。" }, donation: { id: "wuxiang-xingcang", name: "明简", greeting: "今日可择一处设施布施灵石，再记入册中。" } } }, archive: { actors: { keeper: { id: "wuxiang-kongdu", name: "空渡禅师", greeting: "贝叶六匣都在这里，你想先读哪一卷？" } } }, paths: { actors: { guide: { id: "wuxiang-huizhao", name: "慧照", greeting: "壁有明暗两面，你想先照见哪一条道途？" } } }, arena: { actors: { instructor: { id: "wuxiang-jiefeng", name: "法忍禅师", greeting: "神通发于身心，若要调整，先看你当下如何运用。" }, marshal: { id: "wuxiang-huiwu", name: "行觉", greeting: "木人已经归位，有小比在身便可入场。" } } }, cultivation: { actors: { keeper: { id: "wuxiang-zhiguan", name: "寂然禅师", greeting: "一席一灯都已备好，想先问灵效，还是就此入静？" } } }, alchemy: { actors: { keeper: { id: "wuxiang-faming-yaoshi", name: "明恕", greeting: "药性无分净秽，炉火正稳，要问灵效还是开炉？" } } }, refinery: { actors: { keeper: { id: "wuxiang-huoyuan", name: "法圆", greeting: "火候已足，材料也可查验，要问灵效还是炼器？" } } }, spiritVein: { actors: { keeper: { id: "wuxiang-shouyu", name: "慧海", greeting: "窟中今日平稳，巡视封签已经放在案前。" }, facility: { id: "wuxiang-guyu-ku", name: "骨玉窟", greeting: "白色矿髓沿黑岩静静生长，窟中脉息未见异动。" } } }, herbGarden: { actors: { keeper: { id: "wuxiang-huilian", name: "行愿", greeting: "池水无波，草木各循时生长，今日长势已经记下。" }, facility: { id: "wuxiang-xuelian-chi", name: "血莲池", greeting: "暗红池水静映晨光，莲叶托着露珠缓缓舒展。" } } }, gate: { actors: { keeper: { id: "wuxiang-mingmen", name: "道安禅师", greeting: "钟声已过，今日来往与山门近况都可在此问。" }, facility: { id: "wuxiang-buer-men", name: "不二门", greeting: "未合的圆环立在雾中，门前石阶散着新落的叶片。" } } } }, terms: { pathChanges: "道途变化", meridianPractice: "照身参悟", meridianLoadout: "参悟方案", abilityChanges: "三相神通", returnToAffairs: "返回知客寮" } };
class BR extends qt {
    constructor() { super(RR, { organizationTheme: DR }); }
}
var S4 = new BR, d5e = S4.definition;
var VR = { id: "tianyan", name: "天衍圣地", description: "天衍门人兼修金木水火土，以自身法印承接前一道术式。顺其相生可延展法势、滋养生机，执其相克可破护断势；一法既出，下一法仍有不同去处。", raceIds: ["human"], configVersion: 1, methods: [{ id: "tianyan-canon", slot: 1, name: "《天衍五行真经》", isPrimary: !0, description: "以太初为纸，以五行为字。经中不求写尽天数，只教门人辨明一法之后仍有多少去处。" }, { id: "wood-vitality", slot: 2, name: "《青华生元录》", description: "草木荣枯并非两事；生机藏在未尽之处，也藏在愿意重新开始的一息里。" }, { id: "fire-illumination", slot: 3, name: "《离明流火章》", description: "火能照见，也能焚去。持火者先辨所燃为何，方知余烬应当归向何处。" }, { id: "earth-bearing", slot: 4, name: "《坤舆载物篇》", description: "地不与万物争先，却承受每一次落下的重量；能载其重，才能改其势。" }, { id: "metal-severing", slot: 5, name: "《太白裁虚诀》", description: "金气不只断形，也裁去遮蔽与虚妄。锋芒所至，应先知道何物不必留下。" }, { id: "water-flowing", slot: 6, name: "《玄冥行川法》", description: "水无常形，不与一岸相争。去路既改，仍能在曲折中守住归处。" }], abilities: [{ id: "primordial-ray", kind: "default", baseName: "太初玄光", description: "太初灵气无色无形，不入五行。指间玄光只问命中，不替之后的变化作答。", role: "generator", unlock: { type: "method", methodId: "tianyan-canon", level: 1 } }, { id: "verdant-pulse", kind: "active", baseName: "青萝生脉", description: "青萝循气而生，一端缠住敌势，一端牵回施术者尚未断绝的生机。", role: "generator", unlock: { type: "method", methodId: "wood-vitality", level: 1 } }, { id: "myriad-wood-renewal", kind: "active", baseName: "万木回春", description: "不催枯枝强生新叶，只把散落的生机逐寸引回，使该续的一息重新接上。", role: "defensive", unlock: { type: "method", methodId: "wood-vitality", level: 5 } }, { id: "flowing-flame", kind: "active", baseName: "离火流照", description: "离火不作一瞬暴烈，沿气机流照而过；光所及处，余焰仍在暗中寻找可燃之物。", role: "combo", unlock: { type: "method", methodId: "fire-illumination", level: 1 } }, { id: "lotus-in-fire", kind: "active", baseName: "火里种莲", description: "借一线心火焚去附骨之秽，又在余烬中留下一点不肯熄灭的明光。", role: "utility", unlock: { type: "method", methodId: "fire-illumination", level: 5 } }, { id: "earth-bearing-seal", kind: "active", baseName: "坤岳镇形", description: "坤气落下，不急于压碎敌形，先在施术者身前立住一座可承来力的山岳。", role: "defensive", unlock: { type: "method", methodId: "earth-bearing", level: 1 } }, { id: "boundless-earth", kind: "active", baseName: "地载无疆", description: "地不拒轻重，也不问来处。法域展开之时，落在其中的每一道力量都先由厚土承接。", role: "defensive", unlock: { type: "method", methodId: "earth-bearing", level: 5 } }, { id: "metal-cloud-cutter", kind: "active", baseName: "庚金裁云", description: "庚金凝成一线，所裁并非云气，而是藏在云后的护持与虚势。", role: "finisher", unlock: { type: "method", methodId: "metal-severing", level: 1 } }, { id: "white-star-breaker", kind: "active", baseName: "太白破阵", description: "太白一线照入阵眼，先去遮蔽，再断灵机；锋芒不求伤重，只求所见再无虚假。", role: "utility", unlock: { type: "method", methodId: "metal-severing", level: 5 } }, { id: "dark-water-return", kind: "active", baseName: "玄水回澜", description: "玄水不与来势正争，只在回澜时带走立足之力，使快者迟、满者退。", role: "utility", unlock: { type: "method", methodId: "water-flowing", level: 1 } }, { id: "heavenly-river-cleansing", kind: "active", baseName: "天河洗心", description: "引天河过心窍，不洗记忆，也不洗选择，只带走此刻不应继续停留的浊意。", role: "utility", unlock: { type: "method", methodId: "water-flowing", level: 5 } }, { id: "shift-palace", kind: "active", baseName: "移宫换宿", description: "星宿未移，观测之宫先改。法印沿相生次序转过一位，原本无路的下一法便有了新的去处。", role: "utility", unlock: { type: "method", methodId: "tianyan-canon", level: 5 } }, { id: "five-qi-repository", kind: "active", baseName: "五气归藏", description: "推演不必每次走到尽头。将尚未用尽的法印收回太初，余势仍可归为护身、养气与下一法的凭依。", role: "utility", unlock: { type: "method", methodId: "tianyan-canon", level: 10 } }, { id: "tianyan-runtime", kind: "passive", baseName: "太初衍脉", description: "太初灵气本无定色。天衍神通不受异灵根失配影响；与本命灵根相同的法术仍可获得灵根共鸣。", role: "combo", unlock: { type: "always" }, visibility: "internal" }, { id: "hetu-runtime", kind: "passive", baseName: "河图周天", description: "三数成图，令伤势、气血与法力在同一轮转中续接。", role: "combo", unlock: { type: "active_path", pathId: "hetu-evolution" }, visibility: "internal" }, { id: "luoshu-runtime", kind: "passive", baseName: "洛书断局", description: "三数定局，在敌势成形之前追加一次无属性断击。", role: "finisher", unlock: { type: "active_path", pathId: "luoshu-control" }, visibility: "internal" }], onboarding: { initialContribution: 30, initialMethods: { "tianyan-canon": 5, "wood-vitality": 1, "fire-illumination": 1, "earth-bearing": 1, "metal-severing": 1, "water-flowing": 1 }, initialAbilityLoadout: ["verdant-pulse", "flowing-flame", "dark-water-return", "shift-palace"] }, paths: [{ id: "hetu-evolution", name: "河图演生", description: "河图示其流，前法不灭，后法由此而生。三数成图之后，伤势、气血与法力都在同一轮转中得到续接。", minRealm: "筑基", minRealmStage: "中期", layers: [{ id: "1", order: 1, label: "第一层", minRealm: "筑基", minRealmStage: "中期", cost: { cultivationExp: 5000, comprehensionInsight: 100, spiritStones: 25000 } }, { id: "2", order: 2, label: "第二层", minRealm: "金丹", minRealmStage: "圆满", cost: { cultivationExp: 20000, comprehensionInsight: 100, spiritStones: 1e5 } }, { id: "3", order: 3, label: "第三层", minRealm: "化神", minRealmStage: "中期", cost: { cultivationExp: 80000, comprehensionInsight: 100, spiritStones: 400000 } }, { id: "4", order: 4, label: "第四层", minRealm: "炼虚", minRealmStage: "圆满", cost: { cultivationExp: 320000, comprehensionInsight: 100, spiritStones: 1600000 } }, { id: "5", order: 5, label: "第五层", minRealm: "大乘", minRealmStage: "中期", cost: { cultivationExp: 1280000, comprehensionInsight: 100, spiritStones: 6400000 } }, { id: "ultimate", order: 6, label: "终式", minRealm: "渡劫", minRealmStage: "圆满", cost: { cultivationExp: 5120000, comprehensionInsight: 100, spiritStones: 25600000 } }], defaultTacticId: "small-cycle", tactics: [{ id: "small-cycle", name: "小周天", description: "优先选择能够继续反应的落印术，以三行闭环维持周天。" }, { id: "nourish-origin", name: "养元", description: "血线或法力不足时优先内景法，其余时间维持反应。" }, { id: "unbroken-flow", name: "不绝", description: "有印而无可用反应时优先移宫，否则以太初玄光保留法印。" }], presentation: { highlights: [{ name: "三数成图", description: "每三次反应形成一次小周天，同时补充输出与资源。" }, { name: "内外相养", description: "治疗、壁垒和秘法能够进入反应构筑。" }, { name: "留白不断", description: "太初玄光可以等待时机而不破坏法印。" }], abilityChanges: { "tianyan-runtime": "第三次反应触发河图周天，强化主伤害并回复气血与法力。" } }, nodes: [{ id: "hetu-first-number", layerId: "1", name: "初数有应", description: "战斗开始时获得1点衍数。" }, { id: "hetu-lasting-seal", layerId: "1", name: "印留三刻", description: "落印术施加的新法印基础持续时间提高至3回合。" }, { id: "hetu-blank-breath", layerId: "1", name: "太初留白", description: "每回合首次以太初玄光命中带印目标时，回复3%最大法力。" }, { id: "hetu-flow-refund", layerId: "2", name: "法随气转", description: "成功触发反应后，返还本次落印术实际支付的20点法力。" }, { id: "hetu-shift-carries", layerId: "2", name: "移宫承流", description: "移宫换宿成功转化法印时获得1点衍数。" }, { id: "hetu-repository-remnant", layerId: "2", name: "归藏纳余", description: "五气归藏数值收益提高20%，并获得1点衍数。" }, { id: "hetu-verdant-endless", layerId: "3", name: "青华不竭", description: "木行治疗提高25%；首次令目标满血时获得护盾。" }, { id: "hetu-fire-earth-shelter", layerId: "3", name: "火土相庇", description: "降低火里种莲成本并强化地载无疆。" }, { id: "hetu-river-cleansing", layerId: "3", name: "天河洗尘", description: "天河洗心净化3个状态，回复12%最大法力并提高30%控制抗性。" }, { id: "hetu-generation-gate", layerId: "4", name: "生门并开", description: "每次触发化生后回复2%最大气血。" }, { id: "hetu-overcoming-harmony", layerId: "4", name: "克中留和", description: "每次触发冲克后获得3%最大气血护盾。" }, { id: "hetu-three-talents", layerId: "4", name: "三才合契", description: "以三种不同新元素触发反应时，第三术主伤害提高20%。" }, { id: "hetu-scroll-open", layerId: "5", name: "河图开卷", description: "河图周天主伤害增幅提高至35%。" }, { id: "hetu-number-remains", layerId: "5", name: "余数不尽", description: "河图周天结算后保留1点衍数。" }, { id: "hetu-inner-outer", layerId: "5", name: "内外相养", description: "施展内景法后，下一次反应额外获得1点衍数。" }, { id: "hetu-one-line-opens", layerId: "ultimate", name: "一画开天", description: "强化河图周天主伤害与非控制反应数值。" }, { id: "hetu-endless-life", layerId: "ultimate", name: "生生无穷", description: "河图周天额外回复气血与法力，并保留1点衍数。" }, { id: "hetu-escaped-one-returns", layerId: "ultimate", name: "遁一归元", description: "每装备1门非落印主动神通，宗门直接伤害、治疗与护盾提高8%，最多2门。" }] }, { id: "luoshu-control", name: "洛书制化", description: "洛书定其位，不等万法自然流转。移一宫、断一势、藏一印，在敌势真正成形之前先改写它的去处。", minRealm: "筑基", minRealmStage: "中期", layers: [{ id: "1", order: 1, label: "第一层", minRealm: "筑基", minRealmStage: "中期", cost: { cultivationExp: 5000, comprehensionInsight: 100, spiritStones: 25000 } }, { id: "2", order: 2, label: "第二层", minRealm: "金丹", minRealmStage: "圆满", cost: { cultivationExp: 20000, comprehensionInsight: 100, spiritStones: 1e5 } }, { id: "3", order: 3, label: "第三层", minRealm: "化神", minRealmStage: "中期", cost: { cultivationExp: 80000, comprehensionInsight: 100, spiritStones: 400000 } }, { id: "4", order: 4, label: "第四层", minRealm: "炼虚", minRealmStage: "圆满", cost: { cultivationExp: 320000, comprehensionInsight: 100, spiritStones: 1600000 } }, { id: "5", order: 5, label: "第五层", minRealm: "大乘", minRealmStage: "中期", cost: { cultivationExp: 1280000, comprehensionInsight: 100, spiritStones: 6400000 } }, { id: "ultimate", order: 6, label: "终式", minRealm: "渡劫", minRealmStage: "圆满", cost: { cultivationExp: 5120000, comprehensionInsight: 100, spiritStones: 25600000 } }], defaultTacticId: "break-pattern", tactics: [{ id: "break-pattern", name: "破阵", description: "优先触发冲克并利用太白破阵驱散敌方增益。" }, { id: "lock-meridian", name: "锁机", description: "优先准备并触发断脉或泥沼，压缩敌方行动。" }, { id: "decisive-derivation", name: "断局", description: "优先预期直接伤害最高的反应，必要时移宫或归藏。" }], presentation: { highlights: [{ name: "移宫改局", description: "主动转换法印，准备关键冲克。" }, { name: "制化断势", description: "破防、禁法、定身与削攻共同压缩敌方选择。" }, { name: "三数决胜", description: "每三次反应获得一次稳定的无属性爆发。" }], abilityChanges: { "tianyan-runtime": "第三次反应触发洛书断局，追加无属性伤害并强化属性削弱。" } }, nodes: [{ id: "luoshu-first-number", layerId: "1", name: "一数先立", description: "战斗开始时获得1点衍数。" }, { id: "luoshu-observe-gap", layerId: "1", name: "观印知隙", description: "宗门直接伤害对带有天衍法印的目标提高8%。" }, { id: "luoshu-first-change", layerId: "1", name: "第一变", description: "每场战斗首次落印命中无印目标后返还80点实付法力，并使新印持续3回合。" }, { id: "luoshu-fast-shift", layerId: "2", name: "移宫疾算", description: "移宫换宿消耗降至80，冷却降至1回合。" }, { id: "luoshu-reverse-two", layerId: "2", name: "倒演两宫", description: "移宫换宿改为移动两位；下一次反应主伤害提高20%。" }, { id: "luoshu-hidden-counter", layerId: "2", name: "藏印为筹", description: "五气归藏数值收益提高25%，并获得1点衍数。" }, { id: "luoshu-flame-flow", layerId: "3", name: "炎流相激", description: "强化燎原、蒸发与熔金。" }, { id: "luoshu-mountain-wood", layerId: "3", name: "山木倾覆", description: "强化熔岩、泥沼与崩根。" }, { id: "luoshu-metal-water", layerId: "3", name: "金水决机", description: "强化锻锋、寒泉与断脉。" }, { id: "luoshu-lock-position", layerId: "4", name: "定势锁机", description: "提高泥沼与断脉控制命中，并强化抵抗后的替代削弱。" }, { id: "luoshu-exploit-weakness", layerId: "4", name: "乘虚而入", description: "目标拥有普通减益或控制时，宗门直接伤害提高15%。" }, { id: "luoshu-dispel-truth", layerId: "4", name: "斩护见真", description: "每3回合首次触发冲克时，在主伤害前驱散1个普通增益。" }, { id: "luoshu-chain-control", layerId: "5", name: "连环制化", description: "连续反应令后续落印术主伤害提高8%，最多3层。" }, { id: "luoshu-shatter-seal", layerId: "5", name: "碎印夺机", description: "目标低于40%气血时粉碎新印，并追加主伤害45%的无属性伤害。" }, { id: "luoshu-save-error", layerId: "5", name: "失算犹存", description: "每回合首次无反应覆盖时保留旧印。" }, { id: "luoshu-nine-changes", layerId: "ultimate", name: "洛书九变", description: "洛书断局追伤提高至100%，非控制削弱增幅提高至35%。" }, { id: "luoshu-guest-becomes-host", layerId: "ultimate", name: "反客为主", description: "洛书断局后保留1点衍数，并使本次新印持续3回合。" }, { id: "luoshu-heaven-ends", layerId: "ultimate", name: "天机尽处", description: "目标低于35%气血时，冲克主伤害获得按已损气血缩放的法攻系数。" }] }] };
var qR = "tianyan";
var CR = { elderTrial: { name: "观澜真人·试炼化身", description: "以河洛法印推演战局，步步逼问弟子的下一着。" }, facilityNames: { archive: "五经阁", cultivation_room: "太初静室", workshop: "太白铸府" } };
var Ca = (e, i, n, a, t, r, s, o, d) => ({ id: e, label: i, left: n, top: a, route: t, permission: r, note: s, facility: o, visitor: d }), OR = { sectId: qR, announcement: "五峰水脉本旬将依新阵图调度，诸弟子行经中宫时请勿挪动地刻与测算标记。", onboarding: { summary: "以无色太初灵气推演五行，让前一法留下的余势决定后一法的变化。", traits: ["五行生克", "法印衔术", "万法随势"], script: { id: "tianyan-onboarding", title: "天衍有缺", theme: "mist", backdrop: { src: "/assets/sect/onboarding/tianyan.webp", alt: "雨后中宫演法台上，一名新弟子沿石阶走向等候在五行汇流地刻前的执教，五峰殿宇隐于云雾" }, acts: [{ id: "five-peaks-above-clouds", title: "云上五峰", scene: "天衍圣地 · 观象阶", body: "石阶越过云海，五座外峰渐次显出轮廓。玄水自墨青山壁流入药圃，木架与药篓沿廊桥送往暗朱炉院；窑灰归入赭土，矿路再通向覆着白铜屋面的冷峰。所有去路都没有停在一峰，最终绕回雨后的中宫。", speaker: "执教：“先看它们如何相接。记住，五行从来不是五座互不相干的院子。”", backgroundPosition: "50% 38%", tone: "mist" }, { id: "primordial-without-color", title: "太初无色", scene: "天衍圣地 · 中宫演法台", body: "执教站在汇流地刻中央，抬手送出一线无色玄光。灵光越过湿润石面，只留下转瞬即逝的浅白痕迹；它没有火的炽烈，也没有金的锋响，更没有惊动地刻中缓缓流动的水。", speaker: "执教：“这是太初。它不替你选择，所以也不会扰乱你已经留下的答案。”", backgroundPosition: "50% 64%", tone: "stillness" }, { id: "one-art-leaves-mark", title: "一法留痕", scene: "天衍圣地 · 五行地刻", body: "木气掠过傀儡，在执教掌中留下一枚青印。下一刻，火光承印而起，铺向相邻的数具傀儡；掌中青色随之化为赤红，等待下一道法术。", speaker: "执教：“第一法不是未完成的失败。它是在替第二法留下去处。”", backgroundPosition: "72% 58%", tone: "ember" }, { id: "the-escaped-one", title: "随势生变", scene: "天衍圣地 · 五经阁前", body: "五枚经简在案上依次展开。执教先以水势润木，又翻掌运土截断水流；同一枚法印，在不同的下一法中显出不同用途。", speaker: "执教：“五行皆可用，先辨眼前之势。该生时生，该断时断，不必将五行依次走遍。”", backgroundPosition: "28% 42%", tone: "steel" }, { id: "derivation-remains-open", title: "天衍有缺", scene: "天衍圣地 · 衍天殿", body: "你走到执教面前，将本命灵气送入中宫汇流地刻。灵光先随浅水掠过根须，又映过远处炉火与赭色泥沙，最后在白铜冷光中卸去原有偏向，归入一条从未走过的无色经路。五峰没有同时显威，只在云雾之间依次传来回应。", speaker: "掌教：“天机从不因推演而失去变化。今日入门，愿你知其可为，也知其不可尽为。”", backgroundPosition: "50% 56%", tone: "mist" }] } }, map: { image: "/assets/sect/tianyan-map.webp", alt: "天衍圣地五峰环绕中宫，水脉、药圃、炉院、土台与矿路首尾相接的云海舆图", hotspots: [Ca("hall", "衍天殿", "50%", "41%", "/game/sect/hall", "sect.hall.view", "身份 · 同门 · 周俸"), Ca("archive", "五经阁", "29%", "22%", "/game/sect/archive", "sect.archive.use", "心法研习", "archive"), Ca("cliff", "河洛台", "66%", "22%", "/game/sect/enlightenment-cliff", "sect.enlightenment.use", "流派 · 参悟"), Ca("arena", "中宫演法台", "50%", "49%", "/game/sect/arena", "sect.arena.use", "神通 · 战术 · 小比"), Ca("affairs", "司算院", "58%", "47%", "/game/sect/affairs", "sect.tasks.use", "日常 · 周常 · 晋升"), Ca("treasury", "天衡库", "35%", "67%", "/game/sect/treasury", "sect.shop.use", "贡献兑换"), Ca("industries", "营造司", "80%", "60%", "/game/sect/industries", "sect.construction.view", "设施建设 · 灵石捐献"), Ca("cultivation", "太初静室", "15%", "57%", "/game/sect/cultivation-room", "sect.facility.cultivation.use", "闭关修炼 · 设施灵效", "cultivation_room"), Ca("alchemy", "青华丹院", "30%", "29%", "/game/sect/alchemy", "sect.facility.alchemy.use", "炼丹 · 设施灵效", "workshop"), Ca("refinery", "太白铸府", "35%", "75%", "/game/sect/refinery", "sect.facility.refinery.use", "炼器 · 设施灵效", "workshop"), Ca("vein", "坤元地脉", "82%", "54%", "/game/sect/spirit-vein", "sect.spirit_vein.view", "矿场巡视 · 灵石收益 · 采矿", "spirit_vein"), Ca("garden", "长生圃", "26%", "15%", "/game/sect/herb-garden", "sect.herb_garden.view", "草木长势 · 产出待开放", "herb_garden"), Ca("gate", "观象门", "50%", "88%", "/game/sect/gate", "sect.gate.view", "山门动态 · 清扫差事", void 0, { description: "观象门正对云海，外客可在门侧石刻前递交名帖，等待执教回应。" }), Ca("cave", "云衡洞府", "13%", "50%", "/game/sect/cave", "sect.cave.view", "弟子居所"), { id: "formation", label: "五峰归流阵眼", left: "50%", top: "53%", permission: "sect.formation.view", note: "宗门战后续开放", facility: "formation", locked: !0, visitor: { description: "五峰灵机经水脉、炉院与矿路汇入中宫，外客可观其势，不得踏入阵眼。" } }] }, facilityLabels: { archive: "五经阁", cultivation_room: "太初静室", workshop: "太白铸府", spirit_vein: "坤元地脉", herb_garden: "长生圃", formation: "五峰归流阵眼" }, lockedFacilities: ["formation"], scenes: { map: { title: "天衍圣地舆图", description: "五峰环绕中宫，水脉、药圃、炉院、土台与矿路首尾相接；诸峰各有所长，却始终在同一轮推演中运转。", loadingText: "五峰水脉正在归流中宫……" }, hall: { title: "衍天殿", description: "大殿不悬天命判词，只陈历代推演中被事实改写的旧卷。身份玉牒与周俸名册置于中宫汇流地刻之后，雨水沿殿前石槽缓缓分入五峰。" }, affairs: { title: "司算院", description: "新差事依时辰、地脉与人手写入长卷；执事会标出已知条件，却从不替接取者写下唯一答案。" }, archive: { title: "五经阁", description: "六卷真经分藏于中央与五行书架。卷册之间留有大量空白，供后来者记录术法相接时出现的新变化。" }, paths: { title: "河洛台", description: "衍法天师借五行变化延展法势，执衡真君以生克之理破护断势。两条道途同修五行，各有取舍。" }, arena: { title: "中宫演法台", description: "五道地刻汇于圆台。弟子在此更换神通、校验法印，也复盘每一次被错误次序覆盖的余势。" }, cultivation: { title: "太初静室", description: "静室内没有五色阵光，只留一线无色灵气。门人需先让本命之气安静下来，才能重走太初衍脉。" }, alchemy: { title: "青华丹院", description: "木架、活水与温炉依次相连。药师记录的不只是药性，也包括采时、火候和前一炉留下的余温。" }, refinery: { title: "太白铸府", description: "金石在炉火与水渠之间往复，锤下每一道锋面都有明确去处；废料也会归入下一炉，而非弃在山外。" }, spiritVein: { title: "坤元地脉", description: "山腹地脉托住五峰阵基。厚土不显于天际，却决定廊桥、水渠与炉道能否在云雨之后仍守住原位。" }, herbGarden: { title: "长生圃", description: "灵草依水位与日照分层种植。圃中没有永远固定的田垄，每一季都会按照观象记录重新调整。" }, gate: { title: "观象门", description: "山门正对云海，门侧刻着历年天象与实际结果。偏差没有被抹去，反而比准确的预言保存得更久。" }, cave: { title: "云衡洞府", description: "洞府散在玄冥、青华二峰之间。每处门前都嵌一片集露白铜，清晨水痕会留下不同走向，提醒主人今日的判断也会随明日天光改变。" } }, rooms: { affairs: { description: "司算院长卷依时辰铺开，日常、周常与晋升事务各归一席。", actors: { daily: { id: "tianyan-ji-sichen", name: "知微", greeting: "今日时序已经排定，眼下可办的差事都在这里。" }, weekly: { id: "tianyan-xu-hengzhang", name: "玄衡道人", greeting: "本周诸事已有定数，但落子之人仍要你自己选。" }, promotion: { id: "tianyan-rong-guanlan", name: "观澜真人", greeting: "晋升试炼不求捷径，只看你能否辨清下一步。" } } }, hall: { actors: { registry: { id: "tianyan-siming", name: "含章真人", greeting: "玉牒与名录已经复核，你可以从任何一项开始查验。" }, stipend: { id: "tianyan-duzhi", name: "清和", greeting: "本周俸数已按实录核定，领取前也可再核一遍。" } } }, treasury: { actors: { keeper: { id: "tianyan-tianku", name: "怀谷道人", greeting: "常备与轮换库存已经清点，你想先看哪一类？" } } }, industries: { actors: { construction: { id: "tianyan-banji", name: "鸣谦道人", greeting: "各处设施都有实数可查，你想先听哪一项进展？" }, donation: { id: "tianyan-ducai", name: "履霜", greeting: "灵石数目须与建设档位相合，你想投向哪处设施？" } } }, archive: { actors: { keeper: { id: "tianyan-yanshu", name: "既白真人", greeting: "六卷真经都已归位，你想从哪一卷开始研习？" } } }, paths: { actors: { guide: { id: "tianyan-heluozhi", name: "观复真人", greeting: "推演先看已有之势，你想从哪条道途开始辨明？" } } }, arena: { actors: { instructor: { id: "tianyan-douheng", name: "玄同道人", greeting: "神通次序与战术都可重排，先把当前配置展开吧。" }, marshal: { id: "tianyan-jiaochang", name: "景初", greeting: "演武场已经归整，有小比记录便可开场。" } } }, cultivation: { actors: { keeper: { id: "tianyan-shouyi", name: "抱一真人", greeting: "阵中灵气已经归稳，想先查灵效，还是开始闭关？" } } }, alchemy: { actors: { keeper: { id: "tianyan-qinghe", name: "允中道人", greeting: "炉温与水候均在合宜范围，要查灵效还是开炉？" } } }, refinery: { actors: { keeper: { id: "tianyan-baishi", name: "松乔道人", greeting: "金石与地火都已就位，要查灵效还是开始炼器？" } } }, spiritVein: { actors: { keeper: { id: "tianyan-kunyuan", name: "见素", greeting: "今日观测未见异常，矿道巡视封签已经排好。" }, facility: { id: "tianyan-kunyuan-dimai", name: "坤元地脉", greeting: "厚土地脉沉在五峰之下，灵辉沿测线缓缓明灭。" } } }, herbGarden: { actors: { keeper: { id: "tianyan-mushi", name: "元吉", greeting: "水位、日照与长势都已记下，今日值录可以查验。" }, facility: { id: "tianyan-changsheng-pu", name: "长生圃", greeting: "田垄依照水位与日照铺开，新一季灵草正在生长。" } } }, gate: { actors: { keeper: { id: "tianyan-guanxing", name: "望舒", greeting: "今日山门记录已经补全，来往与观象结果都可查问。" }, facility: { id: "tianyan-guanxiang-men", name: "观象门", greeting: "门前云气刚散，石阶上还留着昨夜风雨卷来的落叶。" } } } }, terms: { pathChanges: "河洛变化", meridianPractice: "天衍参悟", meridianLoadout: "推演方案", abilityChanges: "神通衍变", returnToAffairs: "返回司算院" } };
class FR extends qt {
    constructor() { super(VR, { organizationTheme: CR }); }
}
var y4 = new FR, y5e = y4.definition;
var JR = { id: "youdu", name: "幽都", description: "幽都门人通晓三魂七魄，以术伤侵形、魂伤越防，并用蚀魂逐层削弱敌人的气血上限、攻防与治疗。其术起势缓慢，却最擅长让强敌在不知不觉间失去还手之力。", raceIds: ["human"], configVersion: 1, methods: [{ id: "youdu-canon", slot: 1, name: "《幽都魂典》", isPrimary: !0, description: "录三魂往复、七魄离合之理，是幽都诸法的总纲。" }, { id: "three-souls-separation", slot: 2, name: "《三魂离合篇》", description: "辨胎光、爽灵、幽精的去留，从影迹中寻出魂魄缝隙。" }, { id: "forgetful-river-record", slot: 3, name: "《忘川渡夜录》", description: "记黑水涨落与游魂归路，令潮声在形神之间长久回荡。" }, { id: "seven-souls-seizure", slot: 4, name: "《七魄夺形法》", description: "七魄各守形骸一处，去其一，身中灯火便暗一盏。" }, { id: "soul-pinning-ironbook", slot: 5, name: "《镇魂铁册》", description: "以幽都旧铁定影镇魂，使离散之魂不得妄动。" }, { id: "dead-heart-living-spirit", slot: 6, name: "《心死神活诀》", description: "心念寂处，神魂反得清明，不为外法轻易拘束。" }], abilities: [{ id: "one-sigh", kind: "default", baseName: "一叹", description: "叹气若游丝，魂已松三分。", role: "generator", unlock: { type: "method", methodId: "youdu-canon", level: 1 } }, { id: "soul-severing-call", kind: "active", baseName: "离魂引", description: "循一声呼唤牵动游魂，魂愈远，越容易被引出形骸。", role: "generator", unlock: { type: "method", methodId: "three-souls-separation", level: 1 } }, { id: "reveal-shadow", kind: "active", baseName: "照影", description: "影者，魂之迹也；见影如见魂。", role: "utility", unlock: { type: "method", methodId: "three-souls-separation", level: 5 } }, { id: "forgetful-river-tide", kind: "active", baseName: "忘川潮", description: "黑水无舟，闻潮者各自忘归。", role: "combo", unlock: { type: "method", methodId: "forgetful-river-record", level: 3 } }, { id: "seize-soul", kind: "active", baseName: "夺魄", description: "七魄去其一，如灯灭一盏。", role: "combo", unlock: { type: "method", methodId: "seven-souls-seizure", level: 3 } }, { id: "pin-soul", kind: "active", baseName: "镇魂", description: "以幽都之铁钉住影迹，镇汝魂魄，不得妄动。", role: "utility", unlock: { type: "method", methodId: "soul-pinning-ironbook", level: 5 } }, { id: "soul-shall-not-return", kind: "active", baseName: "魂兮不归", description: "归来的呼声止于黑水，此后魂行千里，再无归路。", role: "finisher", unlock: { type: "method", methodId: "youdu-canon", level: 10 } }, { id: "youdu-runtime", kind: "passive", baseName: "心死神活", description: "常驻控制韧性，并在每场第一次受控后自行解脱。", role: "defensive", unlock: { type: "always" }, sourceMethodId: "dead-heart-living-spirit", visibility: "internal" }], onboarding: { initialContribution: 30, initialMethods: { "youdu-canon": 5, "three-souls-separation": 1, "forgetful-river-record": 1, "seven-souls-seizure": 1, "soul-pinning-ironbook": 1, "dead-heart-living-spirit": 1 }, initialAbilityLoadout: ["soul-severing-call", null, null, null] }, paths: [{ id: "tide", name: "招魂渡夜", description: "一声唤名落入黑水，千里游魂都听见自己的回音。此道让忘川一寸寸漫过归路。", minRealm: "筑基", minRealmStage: "中期", layers: [{ id: "1", order: 1, label: "第一层", minRealm: "筑基", minRealmStage: "中期", cost: { cultivationExp: 5000, comprehensionInsight: 100, spiritStones: 25000 } }, { id: "2", order: 2, label: "第二层", minRealm: "金丹", minRealmStage: "圆满", cost: { cultivationExp: 20000, comprehensionInsight: 100, spiritStones: 1e5 } }, { id: "3", order: 3, label: "第三层", minRealm: "化神", minRealmStage: "中期", cost: { cultivationExp: 80000, comprehensionInsight: 100, spiritStones: 400000 } }, { id: "4", order: 4, label: "第四层", minRealm: "炼虚", minRealmStage: "圆满", cost: { cultivationExp: 320000, comprehensionInsight: 100, spiritStones: 1600000 } }, { id: "5", order: 5, label: "第五层", minRealm: "大乘", minRealmStage: "中期", cost: { cultivationExp: 1280000, comprehensionInsight: 100, spiritStones: 6400000 } }, { id: "ultimate", order: 6, label: "终式", minRealm: "渡劫", minRealmStage: "圆满", cost: { cultivationExp: 5120000, comprehensionInsight: 100, spiritStones: 25600000 } }], defaultTacticId: "tide-cycle", tactics: [{ id: "tide-cycle", name: "回潮", description: "优先补忘川并维持三层蚀魂，在终结线兑现。" }, { id: "healer-drown", name: "沉医", description: "维持忘川压疗，在高层窗口优先镇魂。" }, { id: "long-night", name: "长夜", description: "延后终结，维持四层压力，魂火满或低血时再兑现。" }], presentation: { highlights: [{ name: "长夜回潮", description: "忘川对深度蚀魂目标造成更多魂伤。" }, { name: "药石难入", description: "以忘川与蚀魂叠加压缩治疗窗口。" }, { name: "余烬不散", description: "终结之后仍可保留下一轮铺垫。" }], abilityChanges: { "forgetful-river-tide": "忘川在至少3层蚀魂目标上提高20%持续魂伤，并能从每回合首次有效潮伤中获得魂火。", "soul-shall-not-return": "节点可强化逐层魂伤、保留蚀魂、留存魂火或在终结后续接忘川。" } }, nodes: [{ id: "tide-first-ripple", layerId: "1", name: "一水忘川", description: "忘川的直接魂伤与每次持续魂伤提高15%。" }, { id: "tide-call-the-name", layerId: "1", name: "唤名成痕", description: "一叹命中带有忘川的目标时，术伤提高20%并额外获得1点魂火，每回合最多一次。" }, { id: "tide-soul-lantern", layerId: "1", name: "魂灯初照", description: "战斗开始时获得1点魂火。" }, { id: "tide-never-ebbs", layerId: "2", name: "潮声不歇", description: "忘川持续时间由2回合提高到3回合。" }, { id: "tide-no-medicine", layerId: "2", name: "彼岸无医", description: "忘川的受治疗削弱由20%提高到30%。" }, { id: "tide-black-water", layerId: "2", name: "黑水浸魄", description: "带有忘川的目标速度额外降低8%。" }, { id: "tide-three-souls-far", layerId: "3", name: "三魂皆远", description: "蚀魂3层与4层的气血上限与攻防削弱提高到10%与15%。" }, { id: "tide-herbs-fail", layerId: "3", name: "药石难入", description: "蚀魂3层与4层的受治疗削弱提高到40%与60%。" }, { id: "tide-crossing-echo", layerId: "3", name: "渡口回声", description: "每回合第一次对至少4层目标结算忘川时，追加0.12倍法攻魂伤。" }, { id: "tide-no-return-current", layerId: "4", name: "江流不返", description: "忘川对至少4层目标造成的持续魂伤总计提高45%。" }, { id: "tide-cleanse-toll", layerId: "4", name: "洗魂有价", description: "敌人驱散蚀魂层数后受到0.12倍法攻魂伤，自身获得1点魂火，每次行动最多一次。" }, { id: "tide-shoreless", layerId: "4", name: "两岸俱失", description: "不归的速度降低由30%提高到40%；魂兮不归命中后额外获得1点魂火。" }, { id: "tide-hundred-ghosts", layerId: "5", name: "百鬼同哭", description: "目标每次进入5层时追加0.30倍法攻魂伤，同一目标每3回合最多一次。" }, { id: "tide-dream-invasion", layerId: "5", name: "魂梦相侵", description: "目标进入5层时刷新忘川，并立即额外结算一次基础忘川魂伤。" }, { id: "tide-last-ferry", layerId: "5", name: "末渡无舟", description: "带有忘川的目标进入5层时，额外失去10%最大法力。" }, { id: "tide-embers-remain", layerId: "ultimate", name: "不归亦不散", description: "魂兮不归结算后保留2层蚀魂。" }, { id: "tide-lament-deepens", layerId: "ultimate", name: "楚些成悲", description: "魂兮不归每层追加魂伤由0.20提高到0.24。" }, { id: "tide-burial-current", layerId: "ultimate", name: "黑潮送行", description: "魂兮不归结算后给目标施加2回合忘川。" }] }, { id: "decree", name: "镇魄司命", description: "见影而知魂，知魂而书名；铁钉落下之前，门人已量过每一道离身缝隙。", minRealm: "筑基", minRealmStage: "中期", layers: [{ id: "1", order: 1, label: "第一层", minRealm: "筑基", minRealmStage: "中期", cost: { cultivationExp: 5000, comprehensionInsight: 100, spiritStones: 25000 } }, { id: "2", order: 2, label: "第二层", minRealm: "金丹", minRealmStage: "圆满", cost: { cultivationExp: 20000, comprehensionInsight: 100, spiritStones: 1e5 } }, { id: "3", order: 3, label: "第三层", minRealm: "化神", minRealmStage: "中期", cost: { cultivationExp: 80000, comprehensionInsight: 100, spiritStones: 400000 } }, { id: "4", order: 4, label: "第四层", minRealm: "炼虚", minRealmStage: "圆满", cost: { cultivationExp: 320000, comprehensionInsight: 100, spiritStones: 1600000 } }, { id: "5", order: 5, label: "第五层", minRealm: "大乘", minRealmStage: "中期", cost: { cultivationExp: 1280000, comprehensionInsight: 100, spiritStones: 6400000 } }, { id: "ultimate", order: 6, label: "终式", minRealm: "渡劫", minRealmStage: "圆满", cost: { cultivationExp: 5120000, comprehensionInsight: 100, spiritStones: 25600000 } }], defaultTacticId: "pin-the-caster", tactics: [{ id: "pin-the-caster", name: "钉法者", description: "优先照影并压制敌方术者，在关键窗口镇魂。" }, { id: "judge-at-four", name: "四层判决", description: "集中单一目标，达到终结要求立即裁决；司命判词可提前到三层。" }, { id: "take-the-fifth", name: "取其第五", description: "优先触发失魂，再在归窍窗口储存魂火。" }], presentation: { highlights: [{ name: "司命断章", description: "直接魂伤在高层目标上更强。" }, { name: "见影知名", description: "照影将层数进一步化为自身魂伤。" }, { name: "镇魄裁断", description: "在四层抉择控制、失魂或终结。" }], abilityChanges: { "reveal-shadow": "成功施加照影时获得1点魂火；自身对照影目标造成魂伤时，每层蚀魂额外提高1%。", "pin-soul": "节点可强化高层镇魂的命中、速度压制与法力效率。", "soul-shall-not-return": "节点可强化逐层魂伤、把最低终结层数提前到3层，并提供裁决后的资源回转。" } }, nodes: [{ id: "decree-iron-enters-shadow", layerId: "1", name: "铁入其影", description: "夺魄与镇魂的术伤、魂伤各提高20%。" }, { id: "decree-see-true-name", layerId: "1", name: "见影知名", description: "照影持续时间提高到4回合。" }, { id: "decree-guard-the-spirit", layerId: "1", name: "守神如城", description: "控制抗性额外提高10%。" }, { id: "decree-first-soul-taken", layerId: "2", name: "一魄先夺", description: "夺魄的降攻提高到25%，持续时间提高到3回合。" }, { id: "decree-silent-nail", layerId: "2", name: "钉下无声", description: "镇魂法力消耗降低40点。" }, { id: "decree-bright-prison-fire", layerId: "2", name: "狱火照名", description: "三点魂火的直接魂伤增幅由25%提高到35%。" }, { id: "decree-three-souls-leave", layerId: "3", name: "三魂离座", description: "离魂引对至少3层目标的增伤由50%提高到70%。" }, { id: "decree-fix-form-first", layerId: "3", name: "先定其形", description: "每场首次命中照影目标的幽都铺层神通额外增加1层蚀魂。" }, { id: "decree-dead-heart-counter", layerId: "3", name: "心寂反照", description: "心死神活首次解控时获得2点魂火；每回合首次成功抵抗控制也获得2点。" }, { id: "decree-four-gates-closed", layerId: "4", name: "四门皆闭", description: "镇魂命中施法前至少4层目标时，追加0.20倍法攻魂伤，并令其速度降低20%两回合。" }, { id: "decree-punishment-measured", layerId: "4", name: "魂刑有度", description: "失魂被抵抗或控制免疫阻止时，目标攻击与速度仍降低20%两回合。" }, { id: "decree-iron-law", layerId: "4", name: "幽都铁律", description: "对至少4层蚀魂目标施加控制时，控制命中提高15%。" }, { id: "decree-five-souls-scattered", layerId: "5", name: "五魄俱散", description: "目标从失魂回落后，攻击额外降低15%两回合。" }, { id: "decree-returning-barrier", layerId: "5", name: "神归有垣", description: "心死神活首次解控后，获得15%最大气血护盾。" }, { id: "decree-one-name-one-judgment", layerId: "5", name: "一名一判", description: "目标首次进入4层后获得标记；下一次终结命中返还60法力。" }, { id: "decree-verdict", layerId: "ultimate", name: "司命判词", description: "魂兮不归基础魂伤由0.70提高到0.85，并可对3层蚀魂目标施放。" }, { id: "decree-seven-inch-severance", layerId: "ultimate", name: "七寸断魂", description: "魂兮不归每层追加魂伤由0.20提高到0.25。" }, { id: "decree-name-in-youdu", layerId: "ultimate", name: "名落幽都", description: "终结后目标低于35%气血时获得3魂火并返还2回合冷却，每场一次。" }] }] };
var LR = "youdu";
var WR = { elderTrial: { name: "归魂婆婆·试炼化身", description: "携魂灯立于忘川影中，以蚀魂与镇魄逼人守住本心。" }, facilityNames: { archive: "三魂阁", cultivation_room: "返照室", workshop: "镇铁炉", spirit_vein: "黑水阴脉", herb_garden: "返照香圃" } };
var Oa = (e, i, n, a, t, r, s, o, d) => ({ id: e, label: i, left: n, top: a, route: t, permission: r, note: s, facility: o, visitor: d }), ZR = { sectId: LR, announcement: "黑水沿岸近来魂灯摇曳，夜巡弟子须两人同行；若见失名游魂，先引至招魂司登记。", onboarding: { summary: "黑水照影，幽灯唤魂。你将在敌人仍然站立时，一层层取走支撑其形神的力量。", traits: ["蚀魂叠层", "魂伤越防", "禁疗耐控"], script: { id: "youdu-onboarding", title: "一叹入幽都", theme: "stillness", backdrop: { src: "/assets/sect/onboarding/youdu.webp", alt: "幽都山门前，弟子沿三盏魂灯照亮的黑水石径入山，水中倒影与本人错开半步" }, acts: [{ id: "black-water-shadow", title: "黑水有影", scene: "幽都 · 黑水石径", body: "你沿北海石径入山。天上没有月，黑水却照出你的脸。水中那张脸比你迟了一息才抬眼。", backgroundPosition: "48% 54%", tone: "stillness" }, { id: "three-calls", title: "三声唤名", scene: "幽都 · 无日关", body: "山门内有人依次唤出你的姓名、来处与心中最不愿失去之物。前两声都有回音，第三声落下时，身后的影子轻轻动了一下。", speaker: "引路人：“莫回头。能随一声呼唤离身的，未必是鬼，也可能是你自己。”", backgroundPosition: "60% 45%", tone: "mist" }, { id: "seven-lamps", title: "七灯照身", scene: "幽都 · 七魄台", body: "七盏灯从暗处逐一亮起。你每走过一盏，脚步便轻一分，直到分不清是身体在前行，还是影子拖着身体。", backgroundPosition: "35% 48%", tone: "stillness" }, { id: "where-soul-returns", title: "魂归何处", scene: "幽都 · 幽都殿", body: "殿中没有神像，只有一面黑水。掌门问你：若能唤走仇敌的魂，也能唤回他的魂，你以哪一声为本事？你承认自己尚不知道答案。", backgroundPosition: "50% 38%", tone: "mist" }, { id: "one-sigh-entry", title: "一叹入门", scene: "幽都 · 魂灯前", body: "掌门吹灭其中一盏灯，灯焰却出现在你掌心。黑水里的倒影终于与你同时抬头。", speaker: "掌门：“先学叹息。唯有一声叹息，最容易让人忘记守住自己的魂。”", backgroundPosition: "52% 44%", tone: "ember" }] } }, map: { image: "/assets/sect/youdu-map.webp", alt: "幽都宗门舆图，黑水穿过幽都殿、七魄台、照影场与山中诸院", hotspots: [Oa("hall", "幽都殿", "49%", "20%", "/game/sect/hall", "sect.hall.view", "身份 · 同门 · 周俸"), Oa("archive", "三魂阁", "25%", "40%", "/game/sect/archive", "sect.archive.use", "心法研习", "archive"), Oa("cliff", "七魄台", "18%", "24%", "/game/sect/enlightenment-cliff", "sect.enlightenment.use", "流派 · 参悟"), Oa("arena", "照影场", "43%", "57%", "/game/sect/arena", "sect.arena.use", "神通 · 战术 · 小比"), Oa("affairs", "招魂司", "34%", "46%", "/game/sect/affairs", "sect.tasks.use", "日常 · 周常 · 晋升"), Oa("treasury", "玄冥库", "63%", "68%", "/game/sect/treasury", "sect.shop.use", "贡献兑换"), Oa("industries", "黑水坊", "48%", "78%", "/game/sect/industries", "sect.construction.view", "设施建设 · 灵石捐献"), Oa("cultivation", "返照室", "12%", "62%", "/game/sect/cultivation-room", "sect.facility.cultivation.use", "闭关修炼 · 设施灵效", "cultivation_room"), Oa("alchemy", "还魂药庐", "73%", "50%", "/game/sect/alchemy", "sect.facility.alchemy.use", "炼丹 · 设施灵效", "workshop"), Oa("refinery", "镇铁炉", "82%", "71%", "/game/sect/refinery", "sect.facility.refinery.use", "炼器 · 设施灵效", "workshop"), Oa("vein", "黑水阴脉", "90%", "44%", "/game/sect/spirit-vein", "sect.spirit_vein.view", "矿场巡视 · 灵石收益 · 采矿", "spirit_vein"), Oa("garden", "彼岸圃", "70%", "37%", "/game/sect/herb-garden", "sect.herb_garden.view", "草木长势 · 产出待开放", "herb_garden"), Oa("gate", "无日关", "49%", "87%", "/game/sect/gate", "sect.gate.view", "山门动态 · 清扫差事", void 0, { description: "三盏魂灯在无日关外照出访客影子，守关人只接下姓名与来意相符的拜帖。" }), Oa("cave", "寄魂庐", "88%", "31%", "/game/sect/cave", "sect.cave.view", "弟子居所"), { id: "formation", label: "万魂归窍阵", left: "79%", top: "14%", permission: "sect.formation.view", note: "宗门战后续开放", facility: "formation", locked: !0, visitor: { description: "黑水与魂灯牵引归路，外客只能在灯外辨认阵纹，不能越过无日关。" } }] }, facilityLabels: { archive: "三魂阁", cultivation_room: "返照室", workshop: "镇铁炉", alchemy: "还魂药庐", refinery: "镇铁炉", spirit_vein: "黑水阴脉", herb_garden: "彼岸圃", formation: "万魂归窍阵" }, lockedFacilities: ["formation"], scenes: { map: { title: "幽都舆图", description: "黑水自山腹流过两岸诸院，灯影与人影总错开半步。", loadingText: "魂灯正沿黑水次第亮起……" }, hall: { title: "幽都殿", description: "殿中无神像，只有映照姓名、来处与归路的一面黑水。" }, affairs: { title: "招魂司", description: "门人记录失名者、游魂与界隙回声，也护送愿意归去的魂。" }, archive: { title: "三魂阁", description: "六卷心法分藏于三层暗阁，书页以魂灯照见。" }, paths: { title: "七魄台", description: "魂灯照见两条道途，沿着七魄留下的痕迹，静心参悟各自的传承。" }, arena: { title: "照影场", description: "场中不立木人，只以黑水映出每一门神通落在影上的痕迹。" }, cultivation: { title: "返照室", description: "一灯一席，修士在寂静中确认三魂七魄仍各安其位。" }, alchemy: { title: "还魂药庐", description: "返照香与彼岸草分柜存放，药师只治魂魄缝隙，不许强拘生魂。" }, refinery: { title: "镇铁炉", description: "黑水旧铁在低焰中缓慢成形，专用来定影稳神。" }, spiritVein: { title: "黑水阴脉", description: "灵石沿湿冷岩层生长，表面映不出开采者的面孔。" }, herbGarden: { title: "彼岸圃", description: "深色花叶沿黑水两岸生长；药田产出玩法后续开放。" }, gate: { title: "无日关", description: "关外不见日月，三盏魂灯为每个归山者留着方向。" }, cave: { title: "寄魂庐", description: "庐舍门前各悬一灯，灯在便知主人形神安稳。" } }, rooms: { affairs: { description: "招魂司内灯影不灭，日常、周常与晋升事务各由一席经办。", actors: { daily: { id: "youdu-shen-zhaodeng", name: "照灯", greeting: "今日卷宗都在灯下，你想办哪一件，直说便是。" }, weekly: { id: "youdu-bai-shoubu", name: "守簿翁", greeting: "本周功簿已经归拢，你可逐项查验。" }, promotion: { id: "youdu-chu-yingui", name: "归魂婆婆", greeting: "晋升这一关，先要记得自己为何而来。" } } }, hall: { actors: { registry: { id: "youdu-luming", name: "沈故衣", greeting: "你的名字还清楚地留在册上，玉牒和同门名录都可查。" }, stipend: { id: "youdu-fafeng", name: "温婆婆", greeting: "本周该给你的已经备齐，要先核对也不妨。" } } }, treasury: { actors: { keeper: { id: "youdu-shoucang", name: "阮秋声", greeting: "架上的东西都清点过了，你慢慢看，选定再说。" } } }, industries: { actors: { construction: { id: "youdu-zhuming", name: "戚百岁", greeting: "桥、阁与台上的建设都有记录，你想先问哪一处？" }, donation: { id: "youdu-duwu", name: "阿七", greeting: "今日选好一处设施，我替你把灵石记入建设簿。" } } }, archive: { actors: { keeper: { id: "youdu-zhaojuan", name: "褚先生", greeting: "六卷心法都能查阅，你想先从哪一卷看起？" } } }, paths: { actors: { guide: { id: "youdu-yindeng", name: "商无咎", greeting: "路有来处，也有归处；你想先辨哪一条？" } } }, arena: { actors: { instructor: { id: "youdu-shihun", name: "迟归鹤", greeting: "术痕都还留在场中，要调整神通便从当前配置说起。" }, marshal: { id: "youdu-shouchang", name: "桑小满", greeting: "场地已经安静下来，有小比在身便可开始。" } } }, cultivation: { actors: { keeper: { id: "youdu-shoudeng", name: "宁无恙", greeting: "室中一切安稳，想先问灵效，还是现在闭关？" } } }, alchemy: { actors: { keeper: { id: "youdu-huansheng", name: "白蘅", greeting: "香火未断，炉温也合适，要先问灵效还是开炉？" } } }, refinery: { actors: { keeper: { id: "youdu-zhentie", name: "祝余", greeting: "低焰正稳，材料也都归位，要先问灵效还是炼器？" } } }, spiritVein: { actors: { keeper: { id: "youdu-tingyin", name: "贺寒川", greeting: "矿道里没有异动，巡视封签已经备妥。" }, facility: { id: "youdu-heishui-yinmai", name: "黑水阴脉", greeting: "湿冷岩层间灵光幽微，黑水映不出矿壁的深处。" } } }, herbGarden: { actors: { keeper: { id: "youdu-bianhua", name: "柳十三", greeting: "两岸花叶都安稳，今日长势已经记入值录。" }, facility: { id: "youdu-bian-pu", name: "彼岸圃", greeting: "深色花叶沿黑水两岸舒展，水气停在叶尖未散。" } } }, gate: { actors: { keeper: { id: "youdu-shouguan", name: "顾长夜", greeting: "关前今日无事，来往记录都已经归拢。" }, facility: { id: "youdu-wuri-guan", name: "无日关", greeting: "三盏魂灯照着关前石路，阶上落叶仍待清理。" } } } }, terms: { pathChanges: "道途变化", meridianPractice: "七魄参悟", meridianLoadout: "参悟方案", abilityChanges: "魂术变化", returnToAffairs: "返回招魂司" } };
